-- Yone in Chinese and French (French picture coming soon), the Stuttgart medal case with the Fanatics note. Safe to run more than once.
insert into promo_items (id, r, data)
select 'item-10675', 10675, $j${"r": 10675, "id": "item-10675", "cat": "PROMO", "nm": "Yone - Blademaster (Spiritforged Pre-Rift)", "la": "Chinese", "ev": "To be confirmed", "se": "SFD", "ty": "Card", "cn": "116", "ra": "Promo", "do": "Body", "tg": "Champion Unit\nYone\nIonia\nDemon", "fo": true, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "", "inf": "Chinese Pre-Rift promo of Yone - Blademaster (SFD 116/221, promo stamp), the same card as the English Pre-Rift Player Kit promo. The language links connect the versions. The event it was handed out at is still to be confirmed.", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/yone-blademaster-spiritforged-pre-rift-ch-item-10675.webp"}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10675');
insert into promo_items (id, r, data)
select 'item-10676', 10676, $j${"r": 10676, "id": "item-10676", "cat": "PROMO", "nm": "Yone - Blademaster (Spiritforged Pre-Rift)", "la": "French", "ev": "To be confirmed", "se": "SFD", "ty": "Card", "cn": "116", "ra": "Promo", "do": "Body", "tg": "Champion Unit\nYone\nIonia\nDemon", "fo": true, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "", "inf": "French Pre-Rift promo of Yone - Blademaster (SFD 116/221, promo stamp), the same card as the English Pre-Rift Player Kit promo. The language links connect the versions. The event it was handed out at is still to be confirmed."}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10676');
insert into promo_items (id, r, data)
select 'item-10677', 10677, $j${"r": 10677, "id": "item-10677", "cat": "COLLECTIBLE", "nm": "Nation Clash Medal Case (RC Stuttgart)", "la": "English", "ev": "RC - Stuttgart, Germany", "se": "RAD", "ty": "Collectible", "cn": "N/A", "ra": "N/A", "do": "N/A", "tg": "Case\nNation Clash\nEurope National Clash\nRegional Championship", "fo": false, "tn": true, "me": true, "nn": false, "bm": false, "pw": false, "pt": "By itself", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/rc-stuttgart-nation-clash-medal-case-en-item-10677.webp", "inf": "Black hard case with a Riftbound: League of Legends logo card on the lid. It is the packaging the Stuttgart Nation Clash medals (also called the Europe National Clash) were packed in. Riot partnered with Fanatics for these items."}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10677');
update promo_items set data = data || jsonb_build_object('inf',(data->>'inf') || ' The medals came in a black hard case (listed separately). Riot partnered with Fanatics for these items.') where id in ('item-10339','item-10340','item-10341') and (data->>'inf') not like '%Fanatics%';
